declare(strict_types=1);if(PHP_SAPI!=='cli')exit(404);require_once dirname(__DIR__).'/lib/SecureUpdater.php';if(!function_exists('sodium_crypto_sign_detached')){$a=dirname(__DIR__).'/vendor/autoload.php';if(is_file($a))require_once$a;}if(!class_exists('ZipArchive')){fwrite(STDERR,"ZipArchive unavailable\n");exit(1);}$root=dirname(__DIR__);$out=$argv[1]??($root.'/updates/RedFox-signed.zip');$version=trim((string)file_get_contents($root.'/version'));$min=$argv[2]??'1.5.0';$raw=trim((string)(rx_process_environment_value('REDFOX_UPDATE_PRIVATE_KEY')?:''));if(preg_match('/^[a-f0-9]{128}$/i',$raw))$sk=hex2bin($raw);else$sk=base64_decode($raw,true);if(!is_string($sk)||strlen($sk)!==64){fwrite(STDERR,"Set 64-byte REDFOX_UPDATE_PRIVATE_KEY\n");exit(2);}$files=[];$exclude=['config.php'=>1,'.env'=>1,'.env.local'=>1,'.user.ini'=>1,'text.json'=>1,'license.json'=>1,'rx_inline_button_map.json'=>1,'images.jpeg'=>1,'images.jpg'=>1,'custom.jpg'=>1];$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS));foreach($it as$f){if(!$f->isFile()||$f->isLink())continue;$rel=str_replace('\\','/',substr($f->getPathname(),strlen($root)+1));if(isset($exclude[$rel])||preg_match('#^(?:logs|storage|updates|Upload|\.git|node_modules|\.cache)/#',$rel)||str_starts_with($rel,'update-manifest')||str_starts_with($rel,'update-signature')||str_starts_with($rel,'.release-')||realpath($f->getPathname())===realpath($out))continue;$files[$rel]=hash_file('sha256',$f->getPathname());}ksort($files,SORT_STRING);$keyId=(string)(rx_process_environment_value('REDFOX_UPDATE_KEY_ID')?:'primary');$channel=(string)(rx_process_environment_value('REDFOX_UPDATE_CHANNEL')?:'stable');if(!preg_match('/^[A-Za-z0-9._-]{1,100}$/',$keyId)||!in_array($channel,['stable','beta'],true))throw new RuntimeException('Invalid key id/channel');$manifest=['product'=>'redfox','version'=>$version,'key_id'=>$keyId,'channel'=>$channel,'min_current_version'=>$min,'created_at'=>gmdate('c'),'php'=>'^8.4','files'=>$files];$canonical=RedFoxSecureUpdater::canonical($manifest);$sig=sodium_crypto_sign_detached($canonical,$sk);$dir=dirname($out);if(!is_dir($dir))mkdir($dir,0755,true);$z=new ZipArchive();if($z->open($out,ZipArchive::CREATE|ZipArchive::OVERWRITE)!==true)throw new RuntimeException('Cannot create ZIP');foreach($files as$rel=>$hash)$z->addFile($root.'/'.$rel,'RedFox/'.$rel);$z->addFromString('RedFox/update-manifest.json',$canonical);$z->addFromString('RedFox/update-signature.txt',base64_encode($sig));$z->close();echo"BUILT $out\nversion=$version files=".count($files)." sha256=".hash_file('sha256',$out)."\n";
